import copy
import hashlib
import json
import math
import pathlib
import sys

def fail(message):
    raise ValueError(message)

def object_pairs(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            fail("duplicate JSON key")
        result[key] = value
    return result

def finite_float(value):
    number = float(value)
    if not math.isfinite(number):
        fail("non-finite JSON number")
    return number

def parse(raw):
    return json.loads(raw.decode("utf-8"), object_pairs_hook=object_pairs, parse_float=finite_float,
                      parse_constant=lambda value: fail("non-finite JSON number"))

def normalized(value):
    return json.dumps(value, sort_keys=True, separators=(",", ":"),
                      ensure_ascii=False, allow_nan=False).encode("utf-8")

def plans(document):
    if not isinstance(document, dict):
        fail("document is not an object")
    value = document.get("plans")
    if not isinstance(value, dict) or not value:
        fail("plans missing or not a nonempty object")
    return normalized(value)

def compare(canonical, candidate, submission):
    expected = plans(canonical)
    if plans(candidate) != expected:
        fail("candidate task plans differ from canonical plans")
    if plans(submission) != expected:
        fail("submitted plans differ from canonical plans")
    return expected

def reverse_objects(value):
    if isinstance(value, dict):
        return {key: reverse_objects(value[key]) for key in reversed(list(value))}
    if isinstance(value, list):
        return [reverse_objects(item) for item in value]
    return value

def self_test(canonical):
    canonical_bytes = plans(canonical)
    baseline = {"plans": copy.deepcopy(canonical["plans"])}
    positive = 0
    rejected = []
    for candidate, submission in [
        (baseline, baseline),
        (reverse_objects(baseline), reverse_objects(baseline)),
    ]:
        if compare(canonical, candidate, submission) != canonical_bytes:
            fail("positive control failed")
        positive += 1

    def reject(name, change, target="submission"):
        candidate = copy.deepcopy(baseline)
        submission = copy.deepcopy(baseline)
        if target in ("candidate", "both"):
            change(candidate)
        if target in ("submission", "both"):
            change(submission)
        try:
            compare(canonical, candidate, submission)
        except (ValueError, TypeError, KeyError):
            rejected.append(name)
        else:
            fail("negative control passed: " + name)

    nonchecks = [(criterion, index) for criterion, plan in canonical["plans"].items()
                 for index, artifact in enumerate(plan["artifacts"])
                 if artifact.get("type") not in ("log", "assertion")]
    if len(nonchecks) != 9:
        fail("expected all nine registered non-check artifact entries")

    def remove_all(document):
        for plan in document["plans"].values():
            plan["artifacts"] = [item for item in plan["artifacts"]
                                 if item.get("type") in ("log", "assertion")]

    for target in ("submission", "candidate", "both"):
        reject("all-nine-omitted-" + target, remove_all, target)
    for criterion, index in nonchecks:
        reject("omitted-" + criterion + "-" + str(index),
               lambda document, c=criterion, i=index: document["plans"][c]["artifacts"].pop(i))
        reject("altered-path-" + criterion + "-" + str(index),
               lambda document, c=criterion, i=index: document["plans"][c]["artifacts"][i].update(
                   path=document["plans"][c]["artifacts"][i]["path"] + ".altered"))

    for field in ("method", "artifacts", "source_paths", "build", "coverage", "reviewer_id"):
        reject("missing-field-" + field,
               lambda document, key=field: document["plans"]["C1"].pop(key))
    reject("missing-criterion", lambda document: document["plans"].pop("C1"))
    reject("extra-criterion", lambda document: document["plans"].update(C7=copy.deepcopy(document["plans"]["C1"])))
    reject("extra-plan-key", lambda document: document["plans"]["C1"].update(unregistered=True))
    for field, value in [
        ("method", "altered method"),
        ("source_paths", ["altered/source.py"]),
        ("build", "invented-build"),
        ("coverage", ["altered-instance"]),
        ("reviewer_id", "different-reviewer"),
    ]:
        reject("altered-" + field,
               lambda document, key=field, item=value: document["plans"]["C1"].update({key: item}))
    reject("altered-artifact-type", lambda document: document["plans"]["C1"]["artifacts"][0].update(type="altered"))
    reject("extra-artifact-key", lambda document: document["plans"]["C1"]["artifacts"][0].update(unregistered=True))
    reject("added-artifact", lambda document: document["plans"]["C1"]["artifacts"].append({"path": "extra.json", "type": "document"}))
    reject("changed-array-order", lambda document: document["plans"]["C1"]["artifacts"].reverse())
    check_criterion, check_index = next(
        (criterion, index) for criterion, plan in canonical["plans"].items()
        for index, artifact in enumerate(plan["artifacts"]) if "check_id" in artifact)
    reject("altered-check-binding",
           lambda document: document["plans"][check_criterion]["artifacts"][check_index].update(check_id="different-check"))
    for target in ("candidate", "both"):
        reject("altered-method-" + target,
               lambda document: document["plans"]["C1"].update(method="jointly altered"), target)
    for target in ("submission", "candidate", "both"):
        reject("absent-plans-" + target, lambda document: document.pop("plans"), target)
        reject("wrong-type-plans-" + target, lambda document: document.update(plans=[]), target)
    for name, raw in [
        ("duplicate-json-key", b'{"plans":{},"plans":{}}'),
        ("nested-duplicate-json-key", b'{"plans":{"C1":{"method":"a","method":"b"}}}'),
        ("nan-json", b'{"plans":NaN}'),
        ("infinity-json", b'{"plans":Infinity}'),
        ("negative-infinity-json", b'{"plans":-Infinity}'),
        ("overflow-json", b'{"plans":1e9999}'),
        ("invalid-json", b'{"plans":'),
    ]:
        try:
            parse(raw)
        except (ValueError, TypeError):
            rejected.append(name)
        else:
            fail("parser negative control passed: " + name)
    return {"comparison_controls": "PASS", "positive_controls": positive,
            "negative_controls": len(rejected), "noncheck_entries_covered": len(nonchecks),
            "rejected_cases": rejected,
            "limit": "Local comparison controls only; not admission, authority or independent acceptance."}

def main():
    if len(sys.argv) == 3 and sys.argv[1] == "self-test":
        print(json.dumps(self_test(parse(pathlib.Path(sys.argv[2]).read_bytes())), sort_keys=True))
        return 0
    if len(sys.argv) == 5 and sys.argv[1] == "check":
        raw = [pathlib.Path(path).read_bytes() for path in sys.argv[2:]]
        documents = [parse(item) for item in raw]
        try:
            plan_bytes = compare(*documents)
        except (ValueError, TypeError, KeyError) as error:
            print(json.dumps({"comparison": "REJECT", "reason": str(error)}))
            return 1
        print(json.dumps({
            "comparison": "PASS",
            "input_sha256": dict(zip(("canonical_task", "candidate_task", "actual_submission"),
                                    (hashlib.sha256(item).hexdigest() for item in raw))),
            "canonical_plans_sha256": hashlib.sha256(plan_bytes).hexdigest(),
            "normalized_submission_sha256": hashlib.sha256(normalized(documents[2])).hexdigest(),
            "independent_provenance_verification": "required; not performed by this comparator"
        }, sort_keys=True))
        return 0
    fail("usage: self-test CANONICAL_TASK | check CANONICAL_TASK CANDIDATE_TASK ACTUAL_SUBMISSION")

if __name__ == "__main__":
    try:
        sys.exit(main())
    except (OSError, ValueError, TypeError, KeyError, StopIteration) as error:
        print(json.dumps({"comparison": "ERROR", "reason": str(error)}))
        sys.exit(2)
